WHERE 1=1


    AND d.owner_dept_id=#{search.query.ownerDeptId}


    AND d.qualification_status=#{search.query.status}


    AND a.phone_lookup=#{search.phoneLookup} AND a.phone_verified_at IS NOT NULL

        AND (LOCATE(#{search.query.keyword},COALESCE(a.nickname,''))>0
            OR CAST(d.id AS CHAR)=#{search.query.keyword})

mapper.select:



    ORDER BY a.nickname ASC,d.id DESC
    ORDER BY d.id DESC

LIMIT #{search.query.pageSize} OFFSET #{offset}

SELECT dept_id,dept_name,status,del_flag
FROM sys_dept
WHERE dept_id=#{id}

SELECT holder_type,holder_id,order_id
FROM vi_driver_occupancy
WHERE driver_id=#{id}

mapper.sql:
FROM vi_driver_assignment assignment
JOIN vi_order original ON original.id=assignment.order_id
WHERE assignment.driver_id=#{id}



            AND original.dept_id IN
            #{dept}

        AND 1=0

mapper.update:
UPDATE vi_driver_profile SET
training_context_revision=training_context_revision+IF(owner_dept_id <=> #{row.ownerDeptId},0,1), owner_dept_id=#{row.ownerDeptId},new_assignment_enabled=0,
internal_remark=#{row.internalRemark}, version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=#{row.id} AND version=#{row.version}

UPDATE vi_driver_profile
SET new_assignment_enabled=#{enabled},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE id=#{id} AND version=#{version}
